insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('B-01','سجل الأجهزة الطبية وتصنيف خطورتها','BME','["BME", "FAC", "MED", "BEN"]'::jsonb,'أن يكون لكل جهاز طبي رقم أصل وموقع وفئة خطورة وعقد وجدول صيانة معروف، فلا يعمل جهاز خارج السجل.','استلام جهاز جديد (G-07)، نقل جهاز، أو الجرد السنوي.','محضر الاستلام، بيانات الصانع والوكيل، رقم الغرفة من سجل المواقع (F-03).','سجل أجهزة محدّث، ملصق رقم الأصل، فئة الخطورة وجدول الصيانة لكل جهاز.','اكتمال السجل للأجهزة العاملة 100٪؛ تطابق الجرد الميداني مع السجل ≥ 98٪.','[{"unit": "BME", "action": "تسجيل الجهاز: رقم الأصل، الطراز، الرقم التسلسلي، الصانع والوكيل، تاريخ التشغيل، الضمان، العمر الافتراضي، الموقع برقم الغرفة", "sla": "أسبوع من الاستلام", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "BME", "action": "تصنيف الخطورة: داعم للحياة، عالي، متوسط، منخفض؛ ومنه تُحدَّد دورية الصيانة والاستجابة (G-08)", "sla": "مع التسجيل", "where": "نظام الأجهزة", "kind": "decision"}, {"unit": "BME", "action": "لصق رقم الأصل وتاريخ آخر صيانة على الجهاز", "sla": "مع التسجيل", "where": "—", "kind": "step"}, {"unit": "BEN", "action": "إبلاغ الصيانة الطبية قبل نقل أي جهاز بين الأقسام أو المنشآت", "sla": "قبل النقل", "where": "—", "kind": "step", "role": "رئيس القسم الطبي"}, {"unit": "FAC", "action": "ربط موقع الجهاز بسجل الغرف (F-03)", "sla": "أسبوع", "where": "سجل المساحات", "kind": "step"}, {"unit": "BME", "action": "جرد ميداني سنوي ومطابقته مع السجل ومعالجة الفروقات", "sla": "سنوياً", "where": "تقرير الجرد", "kind": "decision"}, {"unit": "MED", "action": "استلام تقرير الجرد كمدخل لخطة الإحلال (E-05)", "sla": "سنوياً", "where": "—", "kind": "step"}]'::jsonb,'الأجهزة الداعمة للحياة تُميَّز في السجل وتُتابع أولاً في كل المؤشرات.',501) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('B-02','الصيانة الوقائية والمعايرة واختبارات السلامة للأجهزة الطبية','BME','["BME", "BEN", "MED", "DIR"]'::jsonb,'أن يعمل كل جهاز طبي بدقة وأمان بصيانة ومعايرة دورية موثقة بحسب الصانع والخطورة.','جدول الصيانة السنوي المستخرج من سجل الأجهزة (B-01).','توصيات الصانع، فئة الخطورة، عقود الخدمة.','تقارير صيانة ومعايرة واختبار سلامة كهربائية، ملصقات بالتاريخ القادم.','إنجاز الوقائية في موعدها: الداعمة للحياة 100٪ وبقية الأجهزة ≥ 95٪.','[{"unit": "BME", "action": "إعداد جدول الصيانة الوقائية والمعايرة السنوي لكل جهاز بحسب الصانع والخطورة", "sla": "بداية السنة", "where": "جدول الصيانة", "kind": "step"}, {"unit": "BEN", "action": "تنسيق إتاحة الجهاز في الموعد مع القسم الطبي، وتوفير بديل للأجهزة الحرجة", "sla": "قبل الموعد بأسبوع", "where": "—", "kind": "step", "role": "رئيس القسم الطبي"}, {"unit": "BME", "action": "تنفيذ الصيانة والمعايرة واختبار السلامة الكهربائية بالفريق الذاتي أو الوكيل (B-03)", "sla": "حسب الجدول", "where": "أمر العمل", "kind": "step"}, {"unit": "BME", "action": "جهاز يفشل في المعايرة أو السلامة: إيقافه بملصق «خارج الخدمة» وفتح بلاغ إصلاح (G-08)", "sla": "فوري", "where": "نظام الأجهزة", "kind": "decision"}, {"unit": "BME", "action": "توثيق التقرير ولصق تاريخ الصيانة القادم", "sla": "نفس اليوم", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "BME", "action": "متابعة المتأخر: أي جهاز داعم للحياة تجاوز موعده يُصعَّد لمدير الإدارة فوراً (R-26)", "sla": "أسبوعياً", "where": "تقرير المتأخر", "kind": "step"}, {"unit": "DIR", "action": "مراجعة نسبة الإنجاز الشهرية", "sla": "شهرياً", "where": "—", "kind": "step"}]'::jsonb,'',502) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('B-03','عقود خدمة الأجهزة الطبية وأداء الوكلاء','BME','["BME", "MED", "DIR", "FIN", "PROC"]'::jsonb,'أن تكون الأجهزة الحرجة مغطاة بعقود خدمة فعّالة، وأن يُقاس أداء الوكيل بنسبة التشغيل وزمن الاستجابة.','انتهاء الضمان، تجديد العقد، أو نهاية كل شهر.','العقود ومؤشراتها، سجل البلاغات وأوامر العمل لكل جهاز.','تقييم شهري لكل عقد، حسومات، توصية التجديد.','نسبة التشغيل للأجهزة الحرجة ≥ 95٪ (مقترح)؛ لا جهاز حرج بلا عقد بعد الضمان.','[{"unit": "BME", "action": "متابعة نهاية الضمان وطلب عقد الخدمة قبل انتهائه بستة أشهر", "sla": "قبل 6 أشهر", "where": "سجل العقود", "kind": "step"}, {"unit": "PROC", "action": "التعاقد وفق النظام", "sla": "حسب النظام", "where": "—", "kind": "step"}, {"unit": "BME", "action": "متابعة الاستجابة والإصلاح ونسبة التشغيل لكل جهاز من سجل البلاغات", "sla": "مستمر", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "BME", "action": "التقييم الشهري للوكيل وحساب الحسومات وفق العقد", "sla": "خلال 5 أيام من نهاية الشهر", "where": "نموذج التقييم", "kind": "decision"}, {"unit": "DIR", "action": "اعتماد التقييم والحسومات", "sla": "3 أيام", "where": "—", "kind": "decision"}, {"unit": "FIN", "action": "الصرف بعد الحسومات", "sla": "حسب الدورة المالية", "where": "—", "kind": "step"}, {"unit": "MED", "action": "استلام ملاحظات أداء الوكلاء كمدخل لتقييم الموردين في الطرح القادم (E-03)", "sla": "سنوياً", "where": "—", "kind": "step"}]'::jsonb,'',503) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('B-04','الاستدعاءات والتنبيهات الفنية للأجهزة الطبية','BME','["BME", "BEN", "MED", "SAF", "DIR"]'::jsonb,'ألا يبقى جهاز مشمول باستدعاء أو تنبيه سلامة في الخدمة دون معالجة موثقة.','تنبيه من الهيئة العامة للغذاء والدواء أو الصانع أو الوكيل.','نص التنبيه، الطرازات والأرقام التسلسلية المشمولة.','قائمة الأجهزة المتأثرة، إجراء معالجة لكل جهاز، إغلاق موثق.','فحص السجل خلال 48 ساعة من التنبيه 100٪؛ إغلاق المعالجة في المهلة.','[{"unit": "BME", "action": "استلام التنبيه وتسجيله وتحديد درجة خطورته", "sla": "يوم", "where": "سجل التنبيهات", "kind": "step"}, {"unit": "BME", "action": "مطابقة الطرازات والأرقام التسلسلية مع سجل الأجهزة (B-01)", "sla": "48 ساعة", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "BME", "action": "الخطر على المريض: إيقاف الأجهزة المتأثرة فوراً وتوفير بديل", "sla": "فوري", "where": "—", "kind": "decision"}, {"unit": "BEN", "action": "إبلاغ الأقسام المستخدمة وتطبيق التعليمات المؤقتة", "sla": "فوري", "where": "—", "kind": "step", "role": "رئيس القسم الطبي"}, {"unit": "BME", "action": "تنفيذ المعالجة مع الوكيل (تحديث، استبدال قطعة، سحب) وتوثيقها لكل جهاز", "sla": "حسب التنبيه", "where": "أمر العمل", "kind": "step"}, {"unit": "SAF", "action": "تسجيل أي حادث مرتبط بالجهاز (H-03)", "sla": "عند الحاجة", "where": "سجل الحوادث", "kind": "step"}, {"unit": "BME", "action": "إغلاق التنبيه بعد معالجة كل الأجهزة وإبلاغ مدير الإدارة", "sla": "عند الاكتمال", "where": "سجل التنبيهات", "kind": "step"}]'::jsonb,'المهلة الافتراضية مقترحة وتُطابق مع تعليمات الجهة المصدرة للتنبيه.',504) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('B-05','إخراج الأجهزة الطبية من الخدمة والتكهين','BME','["BME", "MED", "BEN", "IT", "GEN", "DIR"]'::jsonb,'أن يخرج الجهاز من الخدمة بقرار فني موثق، وتُمحى بياناته، ويُحدَّث السجل، ويُدرج بديله في الخطة.','جهاز تجاوز عمره، أو كلفة إصلاحه > 40٪ من قيمة الاستبدال، أو لا تتوفر قطعه، أو غير آمن.','تقرير حالة الجهاز وتاريخ أعطاله وكلفته.','محضر تكهين معتمد، شهادة محو البيانات، تحديث السجل، توصية إحلال.','لا جهاز مكهَّن يبقى في الموقع أكثر من 30 يوماً؛ محو البيانات 100٪ للأجهزة الحافظة لبيانات المرضى.','[{"unit": "BME", "action": "تقرير فني بالحالة والتاريخ والكلفة والتوصية", "sla": "5 أيام عمل", "where": "تقرير الحالة", "kind": "step"}, {"unit": "BEN", "action": "رأي القسم المستخدم في الحاجة للبديل", "sla": "3 أيام", "where": "—", "kind": "step", "role": "رئيس القسم الطبي"}, {"unit": "DIR", "action": "اعتماد التكهين عبر اللجنة المختصة", "sla": "حسب دورة اللجنة", "where": "محضر التكهين", "kind": "decision"}, {"unit": "IT", "action": "محو بيانات المرضى من الأجهزة الحافظة للبيانات وفصلها عن الشبكة", "sla": "قبل الإخراج", "where": "شهادة المحو", "kind": "step"}, {"unit": "BME", "action": "تحديث سجل الأجهزة إلى «مكهَّن» وإزالة الملصق", "sla": "يوم", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "GEN", "action": "نقل الجهاز إلى مستودع الرجيع أو التخلص الآمن", "sla": "30 يوماً", "where": "—", "kind": "step"}, {"unit": "MED", "action": "إدراج البديل في خطة الإحلال (E-05)", "sla": "مع الخطة", "where": "—", "kind": "step"}]'::jsonb,'',505) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('E-01','حصر الاحتياجات السنوية من الأجهزة والتجهيزات الطبية','MED','["MED", "BEN", "BME", "DIR", "EXEC"]'::jsonb,'خطة احتياجات سنوية مبررة وذات أولوية لكل المنشآت، مبنية على الخدمة والإحلال لا على الطلبات المتفرقة.','دورة التخطيط السنوية.','طلبات المنشآت، تقرير جرد الأجهزة (B-01)، توصيات الإحلال (E-05)، الخدمات الجديدة.','قائمة احتياجات بأولويات وتقديرات كلفة، معتمدة.','اعتماد الخطة قبل بداية السنة المالية؛ نسبة الطلبات خارج الخطة ≤ 10٪.','[{"unit": "MED", "action": "تعميم نموذج طلب الاحتياج على المنشآت مع معايير الأولوية", "sla": "يوليو", "where": "نموذج الاحتياج", "kind": "step"}, {"unit": "BEN", "action": "رفع الاحتياجات بالمبررات: خدمة جديدة، إحلال، زيادة طاقة، متطلب اعتماد", "sla": "أغسطس", "where": "—", "kind": "step", "role": "مدير المنشأة"}, {"unit": "BME", "action": "رأي فني في الأجهزة المطلوب إحلالها وحالتها (B-05)", "sla": "أسبوعان", "where": "—", "kind": "step"}, {"unit": "MED", "action": "ترتيب الأولويات: سلامة المرضى، متطلب الاعتماد، الإحلال، التوسع؛ وتقدير الكلفة", "sla": "سبتمبر", "where": "خطة الاحتياجات", "kind": "decision"}, {"unit": "DIR", "action": "مراجعة الخطة", "sla": "أكتوبر", "where": "—", "kind": "decision"}, {"unit": "EXEC", "action": "اعتماد الخطة والميزانية", "sla": "حسب الدورة المالية", "where": "—", "kind": "decision"}, {"unit": "MED", "action": "إبلاغ المنشآت بالمعتمد وجدولة الطرح (E-02)", "sla": "بعد الاعتماد", "where": "—", "kind": "step"}]'::jsonb,'الطلبات العاجلة خارج الخطة تُرفع بمبرر سلامة أو تعطل خدمة، ويعتمدها مدير الإدارة.',601) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('E-02','المواصفات الفنية للأجهزة الطبية وكراسة الطرح','MED','["MED", "BEN", "BME", "IT", "PRJ", "PROC"]'::jsonb,'مواصفات محايدة وقابلة للتنافس تضمن الأداء السريري وقابلية الصيانة والربط بالأنظمة ومتطلبات الموقع.','احتياج معتمد في الخطة.','متطلبات المستخدم السريري، معايير التوحيد، متطلبات الموقع.','مواصفات معتمدة، جدول متطلبات الموقع، كراسة طرح.','لا مواصفة تُطرح دون مراجعة الصيانة الطبية وتقنية المعلومات (R-29).','[{"unit": "BEN", "action": "تحديد المتطلبات السريرية والكمية", "sla": "أسبوعان", "where": "—", "kind": "step", "role": "المستخدم السريري"}, {"unit": "MED", "action": "صياغة المواصفات بلا انحياز لعلامة تجارية، مع التوحيد ما أمكن", "sla": "أسبوعان", "where": "نموذج المواصفات", "kind": "step"}, {"unit": "BME", "action": "مراجعة قابلية الصيانة: التدريب، القطع، الضمان، عقد الخدمة بعده (B-03)", "sla": "5 أيام عمل", "where": "—", "kind": "step"}, {"unit": "IT", "action": "مراجعة متطلبات الربط والأمن السيبراني (T-03)", "sla": "5 أيام عمل", "where": "—", "kind": "step"}, {"unit": "PRJ", "action": "مراجعة متطلبات الموقع إن كانت تحتاج أعمالاً (G-07)", "sla": "5 أيام عمل", "where": "—", "kind": "step"}, {"unit": "MED", "action": "اعتماد المواصفات النهائية وإعداد كراسة الطرح", "sla": "أسبوع", "where": "كراسة الطرح", "kind": "decision"}, {"unit": "PROC", "action": "الطرح وفق النظام", "sla": "حسب النظام", "where": "—", "kind": "step"}]'::jsonb,'',602) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('E-03','التقييم الفني لعروض الأجهزة الطبية','MED','["MED", "BEN", "BME", "IT", "PROC"]'::jsonb,'اختيار العرض الأنسب فنياً بمعايير معلنة ومصفوفة مطابقة موثقة.','فتح المظاريف وإحالة العروض للتقييم الفني.','العروض، المواصفات، معايير التقييم وأوزانها.','مصفوفة مطابقة، تقرير تقييم فني موقع، توصية.','إنجاز التقييم في المهلة النظامية؛ لا توصية بلا مصفوفة موثقة.','[{"unit": "PROC", "action": "إحالة العروض للجنة الفنية", "sla": "بعد الفتح", "where": "—", "kind": "step"}, {"unit": "MED", "action": "إعداد مصفوفة المطابقة بند بند لكل عرض", "sla": "5 أيام عمل", "where": "مصفوفة المطابقة", "kind": "step"}, {"unit": "BEN", "action": "تقييم سريري وتجربة عملية عند الحاجة", "sla": "حسب الجدول", "where": "—", "kind": "step", "role": "المستخدم السريري"}, {"unit": "BME", "action": "تقييم الخدمة بعد البيع وسجل الوكيل (B-03)", "sla": "3 أيام", "where": "—", "kind": "step"}, {"unit": "IT", "action": "تقييم التوافق والأمن السيبراني", "sla": "3 أيام", "where": "—", "kind": "step"}, {"unit": "MED", "action": "التوصية الفنية الموقعة من اللجنة", "sla": "حسب المهلة", "where": "تقرير التقييم", "kind": "decision"}, {"unit": "PROC", "action": "استكمال الترسية", "sla": "حسب النظام", "where": "—", "kind": "step"}]'::jsonb,'',603) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('E-04','توريد الأجهزة الطبية وتركيبها وتدريب المستخدمين واستلامها','MED','["MED", "BME", "BEN", "IT", "PRJ", "FIN"]'::jsonb,'أن يصل الجهاز إلى موقع جاهز، ويُركَّب ويُختبر، ويتدرب مستخدموه، قبل أن يُصرف ثمنه أو يدخل الخدمة.','أمر الشراء أو العقد.','العقد، المواصفات، جاهزية الموقع (G-07).','محضر استلام مبدئي، محضر تركيب وتشغيل، شهادات تدريب، استلام فني من الصيانة الطبية، مستندات الصرف.','صفر جهاز يدخل الخدمة دون استلام فني؛ التدريب قبل التشغيل 100٪.','[{"unit": "MED", "action": "متابعة جدول التوريد وتأكيد جاهزية الموقع قبل الشحن (G-07)", "sla": "قبل التوريد بأسبوعين", "where": "—", "kind": "step"}, {"unit": "MED", "action": "الاستلام المبدئي: مطابقة الكميات والطرازات والملحقات والوثائق", "sla": "عند الوصول", "where": "محضر الاستلام المبدئي", "kind": "step"}, {"unit": "MED", "action": "التركيب والتشغيل التجريبي من المورد", "sla": "حسب العقد", "where": "—", "kind": "step"}, {"unit": "IT", "action": "الربط بالأنظمة والشبكة (T-03)", "sla": "قبل التشغيل", "where": "—", "kind": "step"}, {"unit": "BEN", "action": "تدريب المستخدمين وتوقيع سجل التدريب", "sla": "قبل التشغيل", "where": "سجل التدريب", "kind": "step", "role": "المستخدم السريري"}, {"unit": "BME", "action": "اختبارات القبول والسلامة الكهربائية والاستلام الفني وتسجيل الجهاز (B-01)", "sla": "أسبوع", "where": "محضر الاستلام الفني", "kind": "decision"}, {"unit": "MED", "action": "إعداد مستندات الصرف بعد الاستلام الفني", "sla": "3 أيام", "where": "—", "kind": "step"}, {"unit": "FIN", "action": "الصرف", "sla": "حسب الدورة المالية", "where": "—", "kind": "step"}]'::jsonb,'',604) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('E-05','خطة الإحلال والاستبدال للأجهزة الطبية','MED','["MED", "BME", "BEN", "DIR"]'::jsonb,'استبدال الأجهزة قبل أن تتعطل الخدمة، بمعايير معلنة لا بالطلبات الطارئة.','دورة التخطيط السنوية، أو توصية تكهين (B-05).','سجل الأجهزة، تاريخ الأعطال والتوقف، كلفة الإصلاح، العمر الافتراضي.','قائمة إحلال لثلاث سنوات بأولويات.','نسبة الأجهزة العاملة بعد عمرها الافتراضي تنخفض سنوياً.','[{"unit": "BME", "action": "استخراج مؤشرات كل جهاز: العمر، أيام التوقف، كلفة الإصلاح، توفر القطع وعقد الخدمة", "sla": "سنوياً", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "MED", "action": "تطبيق معايير الإحلال (R-30) وترتيب الأولويات للسنوات الثلاث", "sla": "سبتمبر", "where": "خطة الإحلال", "kind": "decision"}, {"unit": "BEN", "action": "تأكيد استمرار الحاجة للخدمة", "sla": "أسبوعان", "where": "—", "kind": "step", "role": "مدير المنشأة"}, {"unit": "DIR", "action": "اعتماد الخطة وإدراج سنتها الأولى في احتياجات العام (E-01)", "sla": "أكتوبر", "where": "—", "kind": "decision"}, {"unit": "MED", "action": "متابعة التنفيذ وتحديث الخطة سنوياً", "sla": "سنوياً", "where": "—", "kind": "step"}]'::jsonb,'',605) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('S-01','عقود النظافة ومراقبة جودتها','GEN','["GEN", "BEN", "FAC", "DIR", "FIN"]'::jsonb,'نظافة تُقاس بالتفتيش الدوري بحسب خطورة المنطقة، ويُدفع للمقاول بحسب الجودة المقاسة.','بدء عقد النظافة، وجدول التفتيش، ونهاية كل شهر.','العقد ومؤشراته، تصنيف المناطق بالخطورة، قوائم التفتيش.','تقارير تفتيش، ملاحظات بمهل، تقييم شهري وحسومات.','نتيجة التفتيش ≥ 90٪ في المناطق الحرجة (مقترح)؛ إغلاق الملاحظات في مهلتها ≥ 90٪.','[{"unit": "GEN", "action": "تصنيف المناطق: حرجة (العمليات، العناية، العزل)، عالية، عادية؛ وتحديد دورية التنظيف والتفتيش لكل منها", "sla": "بدء العقد", "where": "خطة النظافة", "kind": "step"}, {"unit": "BEN", "action": "اعتماد مواد التنظيف والتعقيم وطرقها من مكافحة العدوى", "sla": "بدء العقد", "where": "—", "kind": "step", "role": "مكافحة العدوى"}, {"unit": "GEN", "action": "تفتيش دوري بقائمة موحدة ونتيجة رقمية لكل منطقة", "sla": "يومي للحرجة، أسبوعي لغيرها", "where": "قائمة التفتيش", "kind": "step"}, {"unit": "GEN", "action": "إحالة الملاحظات للمقاول بمهلة ومتابعة إغلاقها", "sla": "حسب المهلة", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "ملاحظات النظافة من الجولات الميدانية (F-02) مدخل للتقييم", "sla": "شهرياً", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "التقييم الشهري وحساب الحسومات", "sla": "خلال 5 أيام من نهاية الشهر", "where": "نموذج التقييم", "kind": "decision"}, {"unit": "DIR", "action": "اعتماد التقييم", "sla": "3 أيام", "where": "—", "kind": "decision"}, {"unit": "FIN", "action": "الصرف بعد الحسومات", "sla": "حسب الدورة المالية", "where": "—", "kind": "step"}]'::jsonb,'',701) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('S-02','إدارة النفايات العامة والطبية','GEN','["GEN", "BEN", "SAF", "DIR"]'::jsonb,'فرز النفايات من مصدرها، وتخزينها ونقلها والتخلص منها بأمان عبر مقاول مرخص وبسجل موثق.','التشغيل اليومي، وبدء عقد النفايات.','أنواع النفايات في كل قسم، العقد، الاشتراطات.','نقاط فرز مجهزة، سجل كميات يومي، بيانات شحن موقعة.','صفر خلط للنفايات الطبية بالعامة في التفتيش؛ اكتمال بيانات الشحن 100٪.','[{"unit": "GEN", "action": "تجهيز نقاط الفرز بالحاويات والأكياس الملونة والملصقات لكل نوع", "sla": "مستمر", "where": "—", "kind": "step"}, {"unit": "BEN", "action": "الفرز من المصدر وتدريب الطاقم عليه", "sla": "مستمر", "where": "—", "kind": "step", "role": "مكافحة العدوى"}, {"unit": "GEN", "action": "الجمع الدوري بمسارات وأوقات محددة إلى غرفة التخزين المبردة", "sla": "حسب الجدول", "where": "سجل الجمع", "kind": "step"}, {"unit": "GEN", "action": "التسليم للمقاول المرخص ببيان شحن موقع ووزن", "sla": "حسب الجدول", "where": "بيانات الشحن", "kind": "step"}, {"unit": "SAF", "action": "النفايات الكيميائية والخطرة تُدار وفق H-04", "sla": "حسب الحاجة", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "تفتيش شهري على الفرز والتخزين وتقرير الكميات", "sla": "شهرياً", "where": "تقرير النفايات", "kind": "decision"}, {"unit": "DIR", "action": "مراجعة التقرير والمخالفات", "sla": "ربع سنوي", "where": "—", "kind": "step"}]'::jsonb,'',702) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('S-03','مكافحة الحشرات والقوارض','GEN','["GEN", "BEN", "MNT"]'::jsonb,'منشآت خالية من الحشرات والقوارض ببرنامج وقائي دوري واستجابة سريعة للبلاغات.','البرنامج الدوري، أو بلاغ مشاهدة.','عقد المكافحة، خرائط نقاط الطُعم، المواد المعتمدة.','سجل الزيارات، معالجة البلاغات، إصلاح منافذ الدخول.','الاستجابة لبلاغ المشاهدة خلال 24 ساعة ≥ 95٪.','[{"unit": "GEN", "action": "برنامج دوري بحسب المنطقة، وبمواد معتمدة من مكافحة العدوى", "sla": "شهري", "where": "خطة المكافحة", "kind": "step"}, {"unit": "BEN", "action": "الإبلاغ عن أي مشاهدة بالموقع ورقم الغرفة", "sla": "فوري", "where": "طلبات الخدمات", "kind": "step"}, {"unit": "GEN", "action": "الاستجابة والمعالجة وتوثيقها", "sla": "24 ساعة", "where": "سجل المكافحة", "kind": "step"}, {"unit": "MNT", "action": "إغلاق منافذ الدخول (فتحات، تسربات، أبواب) المحالة من المكافحة", "sla": "حسب الأولوية", "where": "أوامر العمل", "kind": "step"}, {"unit": "GEN", "action": "تحليل البلاغات المتكررة وتعديل البرنامج", "sla": "ربع سنوي", "where": "—", "kind": "decision"}]'::jsonb,'',703) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('S-04','النقل والأثاث غير الطبي','GEN','["GEN", "BEN", "FAC", "BME", "IT"]'::jsonb,'نقل وتأثيث منظم بطلب موثق، ومخزون أثاث معروف، دون نقل أجهزة طبية أو تقنية بغير أقسامها.','طلب نقل أو أثاث، أو انتقال قسم (G-12).','الطلب، المساحة، قائمة المحتويات.','نقل منفذ، سجل أثاث محدث.','تنفيذ الطلبات العادية خلال 3 أيام عمل ≥ 90٪.','[{"unit": "BEN", "action": "رفع طلب النقل أو الأثاث مع الموقع والكمية", "sla": "—", "where": "طلبات الخدمات", "kind": "step"}, {"unit": "GEN", "action": "التحقق من المخزون أو الحاجة للشراء، وجدولة التنفيذ", "sla": "يوم", "where": "—", "kind": "decision"}, {"unit": "BME", "action": "نقل الأجهزة الطبية يتولاه قسمها أو يشرف عليه (B-01)", "sla": "حسب الجدول", "where": "—", "kind": "step"}, {"unit": "IT", "action": "فصل الأجهزة التقنية ونقلها وإعادة ربطها", "sla": "حسب الجدول", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "التنفيذ وتحديث سجل الأثاث", "sla": "3 أيام عمل", "where": "سجل الأثاث", "kind": "step"}, {"unit": "FAC", "action": "تحديث سجل المساحات عند تغيّر الاستخدام (F-03)", "sla": "أسبوع", "where": "سجل المساحات", "kind": "step"}]'::jsonb,'',704) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('S-05','طلبات الخدمات العامة','GEN','["BEN", "FAC", "GEN"]'::jsonb,'كل طلب خدمة عامة يُسجَّل ويُنفَّذ في مهلته ويُغلق بتأكيد من طلبه.','طلب من منشأة عبر القناة الموحدة (G-01).','الطلب ونوعه والموقع.','طلب منفذ ومغلق بتأكيد.','التنفيذ في المهلة ≥ 90٪؛ إعادة الفتح ≤ 5٪.','[{"unit": "FAC", "action": "تصنيف الطلب خدمة عامة وتحويله (G-01)", "sla": "يوم عمل", "where": "سجل الطلبات", "kind": "step"}, {"unit": "GEN", "action": "تحديد المنفذ (فريق ذاتي أو مقاول) والمهلة بحسب النوع", "sla": "يوم", "where": "—", "kind": "decision"}, {"unit": "GEN", "action": "التنفيذ وتحديث حالة الطلب", "sla": "3 أيام عمل للعادي", "where": "—", "kind": "step"}, {"unit": "BEN", "action": "تأكيد التنفيذ أو إعادة الطلب بملاحظة", "sla": "يومان", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "الإغلاق ومراجعة الطلبات المتكررة شهرياً", "sla": "شهرياً", "where": "—", "kind": "step"}]'::jsonb,'',705) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('T-01','البلاغات التقنية والدعم الفني','IT','["BEN", "IT", "DIR"]'::jsonb,'كل بلاغ تقني يُسجَّل بأولويته ويُعالج في مهلته، والمتكرر يُعالج من جذوره.','بلاغ من مستخدم عبر نظام الدعم أو الهاتف.','وصف المشكلة، الجهاز ورقمه، الموقع، الأثر.','بلاغ مغلق بتأكيد المستخدم، قاعدة معرفة محدثة.','الالتزام بالمهل ≥ 90٪؛ رضا المستخدمين ≥ 85٪.','[{"unit": "BEN", "action": "رفع البلاغ عبر نظام الدعم مع الأثر على المرضى إن وجد", "sla": "فوري", "where": "نظام الدعم التقني", "kind": "step", "role": "المستخدم"}, {"unit": "IT", "action": "تصنيف الأولوية (R-33): حرج، عالٍ، عادي، طلب خدمة", "sla": "ساعة", "where": "نظام الدعم التقني", "kind": "decision"}, {"unit": "IT", "action": "الحل عن بعد أو الزيارة الميدانية أو التصعيد للمستوى الثاني أو المورد", "sla": "حسب الأولوية", "where": "—", "kind": "step"}, {"unit": "IT", "action": "أعطال الأنظمة الحرجة (الطوارئ، العمليات، الصيدلية، المختبر): تفعيل خطة الاستمرارية (T-04) وإبلاغ الإدارة", "sla": "فوري", "where": "—", "kind": "decision"}, {"unit": "BEN", "action": "تأكيد الحل", "sla": "يوم", "where": "—", "kind": "step"}, {"unit": "IT", "action": "الإغلاق وتسجيل الحل في قاعدة المعرفة، ومراجعة المتكرر شهرياً", "sla": "شهرياً", "where": "—", "kind": "step"}]'::jsonb,'',801) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('T-02','البنية التحتية التقنية في المشاريع واستلامها','IT','["IT", "PRJ", "MNT"]'::jsonb,'أن تُصمم الشبكات والتيار الخفيف في المشاريع بالمعايير المعتمدة، وتُستلم بشهادات اختبار.','مشروع يتضمن أعمالاً تقنية (G-09).','مخططات المشروع، معايير التجمع التقنية.','مواصفات معتمدة، شهادات اختبار الكوابل، مخططات As-built للشبكات.','لا استلام لأعمال تقنية دون شهادات اختبار 100٪.','[{"unit": "PRJ", "action": "إرسال مخططات النطاق التقني قبل الطرح (G-09)", "sla": "قبل الطرح", "where": "المستندات", "kind": "step"}, {"unit": "IT", "action": "مراجعة المواصفات: غرف الاتصالات، الكوابل، نقاط الشبكة، الشبكة اللاسلكية، الطاقة الاحتياطية", "sla": "5 أيام عمل", "where": "—", "kind": "decision"}, {"unit": "PRJ", "action": "تعديل الوثائق وفق الملاحظات", "sla": "قبل الطرح", "where": "—", "kind": "step"}, {"unit": "IT", "action": "مراجعة مخططات الورشة والمواد التقنية أثناء التنفيذ", "sla": "حسب الاعتمادات", "where": "الاعتمادات", "kind": "step"}, {"unit": "IT", "action": "الاستلام بشهادات اختبار الكوابل ومخططات As-built وتسمية النقاط", "sla": "عند الاستلام", "where": "محضر الاستلام", "kind": "decision"}, {"unit": "MNT", "action": "استلام الطاقة والتبريد لغرف الاتصالات ضمن الصيانة الوقائية", "sla": "عند الاستلام", "where": "—", "kind": "step"}]'::jsonb,'',802) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('T-03','ربط الأجهزة الطبية بالأنظمة والشبكة وأمنها','IT','["IT", "BME", "MED", "BEN"]'::jsonb,'أن يُربط كل جهاز طبي بالأنظمة (HIS/PACS/LIS) بشكل آمن ومعزول، وأن يُعرف كل جهاز على الشبكة.','جهاز جديد يحتاج ربطاً، أو تحديث نظام.','مواصفات الجهاز، متطلبات الربط، سياسة الأمن السيبراني.','جهاز مربوط على شبكة معزولة، سجل الأجهزة الشبكية، اختبار الربط.','لا جهاز طبي على الشبكة دون موافقة تقنية المعلومات (R-34).','[{"unit": "MED", "action": "إرسال متطلبات الربط ضمن المواصفات (E-02)", "sla": "قبل الطرح", "where": "—", "kind": "step"}, {"unit": "IT", "action": "تحديد طريقة الربط والشبكة المعزولة ومتطلبات الأمن", "sla": "5 أيام عمل", "where": "—", "kind": "decision"}, {"unit": "IT", "action": "تنفيذ الربط واختبار تدفق البيانات مع المورد", "sla": "عند التركيب", "where": "—", "kind": "step"}, {"unit": "BME", "action": "التحقق من سلامة عمل الجهاز بعد الربط", "sla": "عند التركيب", "where": "—", "kind": "step"}, {"unit": "BEN", "action": "التحقق السريري من صحة البيانات في النظام", "sla": "عند التشغيل", "where": "—", "kind": "step", "role": "المستخدم السريري"}, {"unit": "IT", "action": "تسجيل الجهاز في سجل الأجهزة الشبكية ومتابعة تحديثاته الأمنية", "sla": "مستمر", "where": "سجل الأصول التقنية", "kind": "step"}]'::jsonb,'',803) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('T-04','النسخ الاحتياطي واستمرارية الأنظمة','IT','["IT", "BEN", "DIR", "SAF"]'::jsonb,'ألا تُفقد البيانات، وأن تستمر الخدمات الحرجة عند تعطل الأنظمة بإجراءات بديلة مجرَّبة.','الجدول الدوري، أو تعطل نظام.','قائمة الأنظمة الحرجة ومتطلبات الاستعادة لكل منها.','نسخ احتياطية موثقة، اختبارات استعادة، إجراءات بديلة ورقية معممة.','نجاح اختبار الاستعادة ربع السنوي 100٪ (R-36).','[{"unit": "IT", "action": "تحديد الأنظمة الحرجة وزمن الاستعادة المقبول لكل منها", "sla": "سنوياً", "where": "خطة الاستمرارية", "kind": "step"}, {"unit": "IT", "action": "تنفيذ النسخ الاحتياطي الدوري ومراقبة نجاحه", "sla": "يومي", "where": "سجل النسخ", "kind": "step"}, {"unit": "IT", "action": "اختبار الاستعادة الفعلي من النسخ", "sla": "ربع سنوي", "where": "تقرير الاختبار", "kind": "decision"}, {"unit": "BEN", "action": "إجراءات بديلة (نماذج ورقية) للأقسام الحرجة عند تعطل الأنظمة، وتدريب الطاقم عليها", "sla": "سنوياً", "where": "—", "kind": "step", "role": "مدير المنشأة"}, {"unit": "SAF", "action": "إدراج تعطل الأنظمة في خطة الطوارئ وتمارينها (H-02)", "sla": "سنوياً", "where": "—", "kind": "step"}, {"unit": "DIR", "action": "مراجعة نتائج الاختبارات", "sla": "ربع سنوي", "where": "—", "kind": "step"}]'::jsonb,'',804) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('T-05','الأصول التقنية وصلاحيات المستخدمين','IT','["IT", "BEN", "DIR"]'::jsonb,'أن يُعرف كل جهاز حاسب وطابعة وشبكة، وأن تُمنح الصلاحيات بقدر الحاجة وتُسحب عند انتهائها.','استلام أجهزة، موظف جديد، نقل أو انتهاء عمل.','سجل الأصول التقنية، طلبات الصلاحيات.','سجل أصول محدث، صلاحيات موثقة، تحديثات أمنية مطبقة.','سحب صلاحيات المغادرين في يومهم 100٪ (R-35)؛ التحديثات الأمنية الحرجة خلال 14 يوماً.','[{"unit": "IT", "action": "تسجيل الأصول التقنية برقم أصل وموقع ومستخدم", "sla": "عند الاستلام", "where": "سجل الأصول التقنية", "kind": "step"}, {"unit": "BEN", "action": "طلب الصلاحيات للموظف الجديد بحسب دوره، وإبلاغ تقنية المعلومات بالمغادرين", "sla": "قبل البدء / يوم المغادرة", "where": "—", "kind": "step", "role": "مدير القسم"}, {"unit": "IT", "action": "منح الصلاحيات بقدر الحاجة وتوثيقها", "sla": "يومان", "where": "—", "kind": "step"}, {"unit": "IT", "action": "سحب الصلاحيات يوم انتهاء العمل", "sla": "نفس اليوم", "where": "—", "kind": "decision"}, {"unit": "IT", "action": "تطبيق التحديثات الأمنية ومراجعة الصلاحيات دورياً", "sla": "شهرياً", "where": "—", "kind": "step"}, {"unit": "DIR", "action": "مراجعة تقرير الصلاحيات والتحديثات", "sla": "ربع سنوي", "where": "—", "kind": "step"}]'::jsonb,'',805) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-25','لكل جهاز طبي رقم أصل وفئة خطورة','الصيانة الطبية','لا يعمل جهاز طبي خارج سجل الأجهزة؛ لكل جهاز رقم أصل وموقع وفئة خطورة وجدول صيانة.','["داعم للحياة، عالي، متوسط، منخفض", "الموقع برقم الغرفة", "إبلاغ الصيانة الطبية قبل أي نقل"]'::jsonb,'BME','B-01','',25) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-26','وقائية الأجهزة الداعمة للحياة لا تتأخر','الصيانة الطبية','تُنجز الصيانة الوقائية والمعايرة للأجهزة الداعمة للحياة في موعدها، ويُصعَّد أي تأخير لمدير الإدارة فوراً.','["الداعمة للحياة 100٪ في موعدها", "بقية الأجهزة ≥ 95٪", "جهاز يفشل في المعايرة يُوقف فوراً"]'::jsonb,'BME','B-02','النسب مقترحة.',26) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-27','الاستدعاءات تُفحص خلال 48 ساعة','الصيانة الطبية','كل تنبيه أو استدعاء لجهاز طبي يُطابق مع السجل خلال 48 ساعة، والجهاز الخطر يُوقف فوراً.','["تسجيل كل تنبيه", "إيقاف الجهاز الخطر وتوفير بديل", "إغلاق موثق لكل جهاز"]'::jsonb,'BME','B-04','المهلة مقترحة.',27) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-28','لا تكهين بلا لجنة ومحو بيانات','الصيانة الطبية','لا يخرج جهاز من الخدمة إلا بتقرير فني واعتماد اللجنة ومحو بيانات المرضى وتحديث السجل.','["تقرير فني بالحالة والكلفة", "شهادة محو البيانات", "إدراج البديل في خطة الإحلال"]'::jsonb,'BME','B-05','',28) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-29','المواصفات تمر بالصيانة الطبية وتقنية المعلومات','التجهيزات الطبية','لا تُطرح مواصفة جهاز طبي قبل مراجعة الصيانة الطبية لقابلية الصيانة وتقنية المعلومات للربط والأمن، والمشاريع لمتطلبات الموقع عند الحاجة.','["مواصفات محايدة بلا علامة تجارية", "تدريب وقطع وضمان وعقد خدمة", "متطلبات الربط والأمن"]'::jsonb,'MED','E-02','',29) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-30','الإحلال بمعايير معلنة','التجهيزات الطبية','يُرشَّح الجهاز للإحلال بمعايير معلنة لا بالطلب الطارئ.','["تجاوز العمر الافتراضي", "كلفة الإصلاح > 40٪ من قيمة الاستبدال", "أيام توقف مرتفعة", "انتهاء دعم الصانع أو توفر القطع"]'::jsonb,'MED','E-05','النسب مقترحة.',30) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-31','الفرز من المصدر','الخدمات العامة','تُفرز النفايات في مكان إنتاجها بحاويات ملونة، ولا تُخلط النفايات الطبية بالعامة في أي مرحلة.','["حاويات وأكياس ملونة وملصقات", "غرفة تخزين مبردة للطبية", "مقاول مرخص وبيان شحن موقع"]'::jsonb,'GEN','S-02','',31) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-32','النظافة تُقاس بالتفتيش','الخدمات العامة','تُقاس جودة النظافة بتفتيش دوري بنتيجة رقمية بحسب خطورة المنطقة، ومنها يُحسب أداء المقاول.','["يومي للمناطق الحرجة", "أسبوعي لغيرها", "الحسومات وفق العقد"]'::jsonb,'GEN','S-01','',32) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-33','أولويات البلاغ التقني','تقنية المعلومات','تُحدد أولوية البلاغ التقني بأثره على المرضى والخدمة.','["حرج: توقف نظام سريري أو منطقة حرجة — استجابة خلال ساعة", "عالٍ: يؤثر على قسم — خلال 4 ساعات", "عادي: مستخدم واحد — خلال يوم عمل", "طلب خدمة: خلال 3 أيام عمل"]'::jsonb,'IT','T-01','المهل مقترحة.',33) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-34','لا جهاز طبي على الشبكة دون موافقة','تقنية المعلومات','لا يُربط جهاز طبي بالشبكة أو الأنظمة دون موافقة تقنية المعلومات وعزله وفق سياسة الأمن.','["شبكة معزولة للأجهزة الطبية", "تسجيل في سجل الأجهزة الشبكية", "متابعة التحديثات الأمنية"]'::jsonb,'IT','T-03','',34) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-35','الصلاحيات بقدر الحاجة','تقنية المعلومات','تُمنح الصلاحيات بقدر الدور وتُسحب يوم انتهاء العمل، وتُراجع دورياً.','["طلب موثق من مدير القسم", "سحب في يوم المغادرة", "مراجعة ربع سنوية"]'::jsonb,'IT','T-05','',35) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-36','النسخ الاحتياطي يُختبر بالاستعادة','تقنية المعلومات','لا يُعد النسخ الاحتياطي ناجحاً إلا باختبار استعادة فعلي دوري، وللأقسام الحرجة إجراءات بديلة مجرَّبة.','["نسخ يومي مراقب", "اختبار استعادة ربع سنوي", "نماذج ورقية بديلة مدرَّب عليها"]'::jsonb,'IT','T-04','',36) on conflict (code) do nothing;
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','هـ. الصيانة الطبية والتجهيزات الطبية','سجل الأجهزة الطبية وتصنيف خطورتها (B-01)','{"BME": "R", "MED": "C", "FAC": "C"}'::jsonb,60 where not exists (select 1 from public.gov_activities where scope='units' and title='سجل الأجهزة الطبية وتصنيف خطورتها (B-01)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','هـ. الصيانة الطبية والتجهيزات الطبية','الاستدعاءات والتنبيهات الفنية للأجهزة (B-04)','{"BME": "R", "MED": "I", "SAF": "C", "DIR": "I"}'::jsonb,61 where not exists (select 1 from public.gov_activities where scope='units' and title='الاستدعاءات والتنبيهات الفنية للأجهزة (B-04)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','هـ. الصيانة الطبية والتجهيزات الطبية','تكهين الأجهزة الطبية (B-05)','{"BME": "R", "MED": "C", "IT": "R", "GEN": "C", "DIR": "A"}'::jsonb,62 where not exists (select 1 from public.gov_activities where scope='units' and title='تكهين الأجهزة الطبية (B-05)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','هـ. الصيانة الطبية والتجهيزات الطبية','عقود خدمة الأجهزة وتقييم الوكلاء (B-03)','{"BME": "R", "MED": "C", "DIR": "A"}'::jsonb,63 where not exists (select 1 from public.gov_activities where scope='units' and title='عقود خدمة الأجهزة وتقييم الوكلاء (B-03)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','هـ. الصيانة الطبية والتجهيزات الطبية','المواصفات الفنية للأجهزة وكراسة الطرح (E-02)','{"MED": "R", "BME": "V", "IT": "V", "PRJ": "C", "DIR": "A"}'::jsonb,64 where not exists (select 1 from public.gov_activities where scope='units' and title='المواصفات الفنية للأجهزة وكراسة الطرح (E-02)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','هـ. الصيانة الطبية والتجهيزات الطبية','التقييم الفني لعروض الأجهزة (E-03)','{"MED": "R", "BME": "C", "IT": "C", "DIR": "A"}'::jsonb,65 where not exists (select 1 from public.gov_activities where scope='units' and title='التقييم الفني لعروض الأجهزة (E-03)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','هـ. الصيانة الطبية والتجهيزات الطبية','خطة الإحلال والاستبدال (E-05)','{"MED": "R", "BME": "C", "DIR": "A", "EXEC": "I"}'::jsonb,66 where not exists (select 1 from public.gov_activities where scope='units' and title='خطة الإحلال والاستبدال (E-05)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','و. الخدمات العامة وتقنية المعلومات','مراقبة جودة النظافة وتقييم المقاول (S-01)','{"GEN": "R", "FAC": "C", "DIR": "A"}'::jsonb,67 where not exists (select 1 from public.gov_activities where scope='units' and title='مراقبة جودة النظافة وتقييم المقاول (S-01)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','و. الخدمات العامة وتقنية المعلومات','إدارة النفايات الطبية والعامة (S-02)','{"GEN": "R", "SAF": "C", "DIR": "I"}'::jsonb,68 where not exists (select 1 from public.gov_activities where scope='units' and title='إدارة النفايات الطبية والعامة (S-02)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','و. الخدمات العامة وتقنية المعلومات','مكافحة الحشرات والقوارض (S-03)','{"GEN": "R", "MNT": "C"}'::jsonb,69 where not exists (select 1 from public.gov_activities where scope='units' and title='مكافحة الحشرات والقوارض (S-03)');
