insert into public.gov_faq(q,a,links,action,sort) select 'كيف نطلب جهازاً طبياً جديداً؟','عبر حصر الاحتياجات السنوي (E-01): ترفع المنشأة الاحتياج بمبرراته، وترتب التجهيزات الطبية الأولويات، ثم المواصفات (E-02) والطرح والتقييم (E-03) والتوريد والاستلام (E-04). العاجل خارج الخطة يُرفع بمبرر سلامة ويعتمده مدير الإدارة.','["E-01", "E-02", "E-04"]'::jsonb,'',28 where not exists (select 1 from public.gov_faq where q='كيف نطلب جهازاً طبياً جديداً؟');
insert into public.gov_faq(q,a,links,action,sort) select 'ماذا نفعل عند تنبيه أو استدعاء لجهاز طبي؟','تسجله الصيانة الطبية وتطابقه مع سجل الأجهزة خلال 48 ساعة، وتوقف الجهاز الخطر فوراً مع بديل، وتبلغ الأقسام، ثم تعالج كل جهاز وتغلق التنبيه بتوثيق (B-04، R-27).','["B-04", "R-27"]'::jsonb,'',29 where not exists (select 1 from public.gov_faq where q='ماذا نفعل عند تنبيه أو استدعاء لجهاز طبي؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف يُكهَّن جهاز طبي؟','بتقرير فني من الصيانة الطبية ورأي القسم، واعتماد اللجنة، ومحو بيانات المرضى من تقنية المعلومات، وتحديث السجل، وإدراج البديل في خطة الإحلال (B-05، R-28).','["B-05", "R-28"]'::jsonb,'',30 where not exists (select 1 from public.gov_faq where q='كيف يُكهَّن جهاز طبي؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف أبلغ عن عطل تقني؟','عبر نظام الدعم التقني مع ذكر الأثر على المرضى. الأولوية بحسب الأثر (R-33): حرج خلال ساعة، عالٍ خلال 4 ساعات، عادي خلال يوم عمل (T-01).','["T-01", "R-33"]'::jsonb,'',31 where not exists (select 1 from public.gov_faq where q='كيف أبلغ عن عطل تقني؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف تُدار النفايات الطبية؟','تُفرز من مصدرها بالحاويات الملونة، وتُجمع إلى غرفة تخزين مبردة، وتُسلَّم لمقاول مرخص ببيان شحن موقع؛ والخطرة والكيميائية مع الأمن والسلامة (S-02، R-31، H-04).','["S-02", "R-31"]'::jsonb,'',32 where not exists (select 1 from public.gov_faq where q='كيف تُدار النفايات الطبية؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف أطلب نقل أثاث أو قسم؟','طلب خدمة عامة بالموقع والكمية (S-04)؛ الأجهزة الطبية تنقلها الصيانة الطبية والتقنية تنقلها تقنية المعلومات، وانتقال قسم كامل يمر بإدارة التغيير في المساحات (G-12).','["S-04", "G-12"]'::jsonb,'',33 where not exists (select 1 from public.gov_faq where q='كيف أطلب نقل أثاث أو قسم؟');
